package sohal.lld.chess.entity.playable;import sohal.lld.chess.entity.Color;import sohal.lld.chess.entity.board.Board;import sohal.lld.chess.entity.board.Cell;public abstract class Piece {    private Color color;    public Piece(Color color) {        this.color = color;    }    public Color getColor() {        return color;    }    abstract public boolean canMove(Board board, Cell start, Cell end);}